@misc{StacksProject,
  author = {{The Stacks Project Authors}},
  title = {The Stacks Project},
  year = {2026},
  url = {https://stacks.math.columbia.edu},
  source_note = {Tags 08J5, 0FLJ, 0F16, 012K and 0FKU; accessed 17 November 2026.},
  verification = {verified at listed scope},
  note = {Verified in this writing on 18 November 2026 at these loci only. Tags0AUW,012O,012U,012W,011N,011O; complete displayed statements and proofs where supplied. Scope: Opened each exact primary tag. These supply torsion-free versus flat over a DVR, the actual functorial filtered-complex morphism, finite-filtration convergence, and permanent-cycle definitions. The candidate-specific transgression and the proper topological fibre-identification remain separate explicit inputs. Tag07VK, Lemma30.22.1, complete statement and proof. Scope: Opened the complete primary statement and proof on the project website. A proper morphism to a Noetherian affine base and a coherent sheaf flat over that base have perfect derived global sections and arbitrary derived base change. The proof uses a bounded flat Cech complex, finite cohomology and the square-zero extension to prove finite Tor amplitude. These exact hypotheses hold for the proper flat elliptic family and the invertible line in K8. Combined fibre acyclicity with the local minimal-complex argument; no smooth-fibre-only replacement is used. Author/title and attached or reproduced edition validated. Current verification applies only to these exact locators; no full-proof or different-edition scope is inferred. Opened19November2026: Cohomology of Sheaves chapter version ed88ff78,14July2026, Lemma13.4p22 (global20.13.4,Tag01F2), Lemma18.1p30 (global20.18.1,Tag09V5) and Theorem18.2pp30--31 (global20.18.2,Tag09V6). Scope: constant-integer sheaf Leray sequence and the actual stalk-to-fibre proper-base-change map for the compact Hausdorff F2.6 construction.}
}

